<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import AppLayout from '../components/layout/AppLayout.vue'; import BaseButton from '../components/ui/BaseButton.vue'; import { analyzeWorkbook, previewWorkbook, commitWorkbook, type ImportAnalysis, type ImportPreview, type ImportResult } from '../services/imports'; import { listCategories } from '../services/categories'; import { apiErrorMessage } from '../services/api'; import { formatMoney } from '../utils/formatters'; import type { Category } from '../types';
const step = ref(1); const file = ref<File | null>(null); const analysis = ref<ImportAnalysis | null>(null); const preview = ref<ImportPreview | null>(null); const result = ref<ImportResult | null>(null); const categories = ref<Category[]>([]); const selected = ref<string[]>([]); const categoryMap = ref<Record<string, string>>({}); const busy = ref(false); const error = ref(''); const importable = computed(() => analysis.value?.sheets.filter(s => s.importable) ?? []); const mappingFields = ['expense_date', 'description', 'category', 'amount', 'payment_status', 'payment_method', 'payer'];
function pick(event: Event): void { file.value = (event.target as HTMLInputElement).files?.[0] ?? null; }
async function analyze(): Promise<void> { if (!file.value) return; busy.value = true; try { analysis.value = await analyzeWorkbook(file.value); selected.value = importable.value.map(s => s.name); step.value = 2; error.value = ''; } catch (e) { error.value = apiErrorMessage(e); } finally { busy.value = false; } }
async function buildPreview(): Promise<void> { if (!analysis.value) return; const sheets = analysis.value.sheets.filter(s => selected.value.includes(s.name) && s.header_row).map(s => ({ name: s.name, header_row: s.header_row!, mapping: s.suggested_mapping })); busy.value = true; try { preview.value = await previewWorkbook(analysis.value.batch.id, sheets); categoryMap.value = Object.fromEntries(preview.value.unknown_categories.map(name => [name, 'skip'])); step.value = 3; } catch (e) { error.value = apiErrorMessage(e); } finally { busy.value = false; } }
async function commit(): Promise<void> { if (!analysis.value) return; busy.value = true; try { result.value = await commitWorkbook(analysis.value.batch.id, categoryMap.value); step.value = 4; } catch (e) { error.value = apiErrorMessage(e); } finally { busy.value = false; } }
onMounted(async () => { try { categories.value = await listCategories(); } catch { categories.value = []; } });
</script>
<template><AppLayout><div><p class="text-sm font-medium text-brand-700">Administration</p><h1 class="mt-1 text-3xl font-semibold">Import workbook</h1><p class="mt-1 text-sm text-slate-500">Review sheets and row validation before writing expenses.</p></div><div class="mt-6 flex gap-2 text-sm"><span v-for="n in 4" :key="n" class="rounded-full px-3 py-1" :class="step >= n ? 'bg-brand-600 text-white' : 'bg-slate-200'">{{ n }}</span></div><p v-if="error" class="mt-5 rounded-lg bg-red-50 p-3 text-red-700">{{ error }}</p><section v-if="step === 1" class="card mt-6"><h2 class="font-semibold">1. Upload Excel workbook</h2><input class="field mt-4" type="file" accept=".xlsx,.xls,.csv" @change="pick" /><BaseButton class="mt-4" :disabled="!file" :loading="busy" @click="analyze">Analyze workbook</BaseButton></section><section v-else-if="step === 2 && analysis" class="card mt-6"><h2 class="font-semibold">2. Select ledger sheets and review mappings</h2><p v-if="analysis.duplicate_file" class="mt-3 rounded-lg bg-amber-50 p-3 text-sm text-amber-800">This exact file was imported before. Duplicate expense rows will be skipped.</p><div class="mt-4 space-y-3"><div v-for="sheet in analysis.sheets" :key="sheet.name" class="rounded-lg border p-3"><label class="flex items-start gap-3"><input v-model="selected" type="checkbox" :value="sheet.name" :disabled="!sheet.importable" class="mt-1" /><span><strong>{{ sheet.name }}</strong><small class="block text-slate-500">{{ sheet.importable ? `Header row ${sheet.header_row}; last data row ${sheet.highest_row}` : 'No expense ledger headers detected' }}</small></span></label><div v-if="sheet.importable && selected.includes(sheet.name)" class="mt-3 grid grid-cols-2 gap-2 sm:grid-cols-4"><label v-for="field in mappingFields" :key="field" class="text-xs capitalize text-slate-500">{{ field.replaceAll('_',' ') }}<input v-model="sheet.suggested_mapping[field]" class="field" placeholder="Column letter" /></label></div></div></div><BaseButton class="mt-4" :disabled="!selected.length" :loading="busy" @click="buildPreview">Validate selected sheets</BaseButton></section><section v-else-if="step === 3 && preview" class="mt-6 space-y-5"><div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><div class="card"><p class="text-sm text-slate-500">Valid rows</p><p class="mt-2 text-2xl font-semibold">{{ preview.valid_count }}</p></div><div class="card"><p class="text-sm text-slate-500">Invalid rows</p><p class="mt-2 text-2xl font-semibold">{{ preview.invalid_count }}</p></div><div class="card"><p class="text-sm text-slate-500">Potential duplicates</p><p class="mt-2 text-2xl font-semibold">{{ preview.duplicate_count }}</p></div><div class="card"><p class="text-sm text-slate-500">Valid total</p><p class="mt-2 text-2xl font-semibold">{{ formatMoney(preview.valid_total) }}</p></div></div><section v-if="preview.unknown_categories.length" class="card"><h2 class="font-semibold">Unknown categories</h2><div class="mt-3 space-y-2"><label v-for="name in preview.unknown_categories" :key="name" class="flex items-center justify-between gap-3 text-sm"><span>{{ name }}</span><select v-model="categoryMap[name]" class="field mt-0 w-auto"><option value="skip">Skip rows with this category</option><option value="create">Create category</option><option v-for="category in categories" :key="category.id" :value="String(category.id)">Map to {{ category.name }}</option></select></label></div></section><section class="overflow-hidden rounded-xl border bg-white"><div class="max-h-96 overflow-auto"><table class="w-full text-left text-sm"><thead class="sticky top-0 bg-slate-50"><tr><th class="p-3">Source</th><th class="p-3">Date</th><th class="p-3">Description</th><th class="p-3">Amount</th><th class="p-3">Validation</th></tr></thead><tbody class="divide-y"><tr v-for="row in preview.rows" :key="row.id"><td class="p-3">{{ row.sheet_name }} #{{ row.row_number }}</td><td class="p-3">{{ row.values.expense_date }}</td><td class="p-3">{{ row.values.description }}</td><td class="p-3">{{ row.values.amount }}</td><td class="p-3" :class="row.errors.length ? 'text-red-700' : row.status === 'duplicate' ? 'text-amber-700' : 'text-emerald-700'">{{ row.status === 'duplicate' ? 'Potential duplicate — will be skipped' : (row.errors.join(' ') || 'Ready') }}</td></tr></tbody></table></div></section><BaseButton :loading="busy" :disabled="!preview.valid_count" @click="commit">Import valid rows</BaseButton></section><section v-else-if="step === 4 && result" class="card mt-6"><h2 class="text-xl font-semibold">Import complete</h2><dl class="mt-5 grid gap-4 sm:grid-cols-2"><div><dt class="text-sm text-slate-500">Imported</dt><dd class="text-2xl font-semibold">{{ result.imported_count }}</dd></div><div><dt class="text-sm text-slate-500">Duplicates skipped</dt><dd class="text-2xl font-semibold">{{ result.duplicate_count }}</dd></div><div><dt class="text-sm text-slate-500">Invalid rows</dt><dd class="text-2xl font-semibold">{{ result.invalid_count }}</dd></div><div><dt class="text-sm text-slate-500">Category rows skipped</dt><dd class="text-2xl font-semibold">{{ result.skipped_count }}</dd></div><div><dt class="text-sm text-slate-500">Source total</dt><dd class="font-semibold">{{ formatMoney(result.verification.source_total) }}</dd></div><div><dt class="text-sm text-slate-500">Database total</dt><dd class="font-semibold">{{ formatMoney(result.verification.database_total) }}</dd></div></dl><div v-if="result.problem_rows.length" class="mt-5"><h3 class="font-semibold">Skipped and invalid rows</h3><ul class="mt-2 space-y-1 text-sm text-slate-600"><li v-for="row in result.problem_rows" :key="row.id">{{ row.sheet_name }} row {{ row.row_number }}: {{ row.errors.join(' ') || row.status }}</li></ul></div><p class="mt-5 rounded-lg p-3 text-sm" :class="Number(result.verification.difference) === 0 ? 'bg-emerald-50 text-emerald-800' : 'bg-amber-50 text-amber-800'">Difference: {{ formatMoney(result.verification.difference) }}</p><div class="mt-5 grid gap-5 sm:grid-cols-2"><div><h3 class="font-semibold">Payment totals</h3><p v-for="(total, status) in result.verification.payment_totals" :key="status" class="mt-1 flex justify-between text-sm"><span class="capitalize">{{ status }}</span><span>{{ formatMoney(total) }}</span></p></div><div><h3 class="font-semibold">Category totals</h3><p v-for="(total, category) in result.verification.category_totals" :key="category" class="mt-1 flex justify-between text-sm"><span>{{ category }}</span><span>{{ formatMoney(total) }}</span></p></div></div></section></AppLayout></template>
